INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5036521, 733940, 65234, '<td valign="top">Indeed.  Without the person I would have no concept of the vastness of this scene.  Nice lines to the composition, too.</td>', 'Indeed.  Without the person I would have no concept of the vastness of this scene.  Nice lines to the composition, too.', '2008-11-01 12:08:57.000000', NULL, 1),
(5036523, 735469, 3306, '<td valign="top">Outstanding picture. I like your choice of a soft sepia tone. Definitely worth hanging on the wall.</td>', 'Outstanding picture. I like your choice of a soft sepia tone. Definitely worth hanging on the wall.', '2008-11-01 12:09:21.000000', NULL, 1),
(5036524, 734942, 65234, '<td valign="top">A Self-actualized Pelican!  They''re quite rare, I understand ;-)  Love the detail, though those spiky bits look like they''d be really hard on his feet.</td>', 'A Self-actualized Pelican!  They''re quite rare, I understand ;-)  Love the detail, though those spiky bits look like they''d be really hard on his feet.', '2008-11-01 12:11:18.000000', NULL, 1),
(5036528, 731881, 65234, '<td valign="top">Very nice composition :-)</td>', 'Very nice composition :-)', '2008-11-01 12:13:28.000000', NULL, 1),
(5036533, 734789, 65234, '<td valign="top">Lovely dog portrait :-)</td>', 'Lovely dog portrait :-)', '2008-11-01 12:15:04.000000', NULL, 1),
(5036535, 734797, 65234, '<td valign="top">Looks like a truly awesome place.</td>', 'Looks like a truly awesome place.', '2008-11-01 12:15:51.000000', NULL, 1),
(5036540, 735432, 65234, '<td valign="top">Gorgeous light :-)</td>', 'Gorgeous light :-)', '2008-11-01 12:17:21.000000', NULL, 1),
(5036541, 735469, 65234, '<td valign="top">Looks great in sepia.</td>', 'Looks great in sepia.', '2008-11-01 12:18:00.000000', NULL, 1),
(5036543, 734696, 65234, '<td valign="top">Nice light and detail on the Sparrow.  I would crop tighter on top to get rid of the leaves as they don''t enhance the composition IMO.</td>', 'Nice light and detail on the Sparrow.  I would crop tighter on top to get rid of the leaves as they don''t enhance the composition IMO.', '2008-11-01 12:19:00.000000', NULL, 1),
(5036544, 735389, 62895, '<td valign="top">It looks like an advertisement for a travel agency. I like the reflective mood of this photo.</td>', 'It looks like an advertisement for a travel agency. I like the reflective mood of this photo.', '2008-11-01 12:19:03.000000', NULL, 1),
(5036548, 735302, 62895, '<td valign="top">The focus is sharp, but the subject matter is relatively uninteresting,and the blown out sky detracts from the overall effect.</td>', 'The focus is sharp, but the subject matter is relatively uninteresting,and the blown out sky detracts from the overall effect.', '2008-11-01 12:20:23.000000', NULL, 1),
(5036549, 735060, 65234, '<td valign="top">Some sort of "pass the twig" game?  Really interesting captue :-)</td>', 'Some sort of "pass the twig" game?  Really interesting captue :-)', '2008-11-01 12:20:25.000000', NULL, 1),
(5036555, 734789, 3306, '<td valign="top">I love this picture. I am very sentimental about border collies. Mine passed away last year. My best friend. Great shot. great colors. Good composition with the off center crop.</td>', 'I love this picture. I am very sentimental about border collies. Mine passed away last year. My best friend. Great shot. great colors. Good composition with the off center crop.', '2008-11-01 12:26:39.000000', NULL, 1),
(5036558, 733772, 62895, '<td valign="top">I like the dreamy processing, great clouds and soft colors.</td>', 'I like the dreamy processing, great clouds and soft colors.', '2008-11-01 12:26:48.000000', NULL, 1),
(5036560, 735003, 3306, '<td valign="top">Good choice of wide angle lens enabling you to get it all. Interesting shot.</td>', 'Good choice of wide angle lens enabling you to get it all. Interesting shot.', '2008-11-01 12:27:37.000000', NULL, 1),
(5036561, 733055, 65234, '<td valign="top">Like someone took a giant bite out the tree.  Man does some ugly things in the name of progress.</td>', 'Like someone took a giant bite out the tree.  Man does some ugly things in the name of progress.', '2008-11-01 12:27:53.000000', NULL, 1),
(5036562, 735465, 62895, '<td valign="top">Great view! The sky is a little plain, and the foreground is a bit distracting, but the mountains are very lush looking. :-)</td>', 'Great view! The sky is a little plain, and the foreground is a bit distracting, but the mountains are very lush looking. :-)', '2008-11-01 12:29:23.000000', NULL, 1),
(5036563, 732258, 3306, '<td valign="top">Excellent composition. Very good DOF. The sky is great. Really makes the viewer feel small compared to the tower.</td>', 'Excellent composition. Very good DOF. The sky is great. Really makes the viewer feel small compared to the tower.', '2008-11-01 12:29:33.000000', NULL, 1),
(5036565, 733570, 65234, '<td valign="top">I can see the smile in her eyes :-)</td>', 'I can see the smile in her eyes :-)', '2008-11-01 12:30:10.000000', NULL, 1),
(5036566, 731881, 62895, '<td valign="top">Great colors and subject. Excellent use of framing as well.</td>', 'Great colors and subject. Excellent use of framing as well.', '2008-11-01 12:30:45.000000', NULL, 1),
(5036569, 735459, 65234, '<td valign="top">Fabulous perspective!!  The person''s detail is all in the shadow, which is very cool.</td>', 'Fabulous perspective!!  The person''s detail is all in the shadow, which is very cool.', '2008-11-01 12:32:12.000000', NULL, 1),
(5036570, 735096, 62895, '<td valign="top">This place looks like it has a lot of character, but the lights and signs/flags are a little overwhelming. There is a little to much to look at.</td>', 'This place looks like it has a lot of character, but the lights and signs/flags are a little overwhelming. There is a little to much to look at.', '2008-11-01 12:32:36.000000', NULL, 1),
(5036572, 734999, 65234, '<td valign="top">What a great capture!</td>', 'What a great capture!', '2008-11-01 12:33:18.000000', NULL, 1),
(5036573, 735381, 62895, '<td valign="top">Cool subject, the lighting is a little flat but the clarity is great.</td>', 'Cool subject, the lighting is a little flat but the clarity is great.', '2008-11-01 12:33:25.000000', NULL, 1),
(5036574, 735130, 3306, '<td valign="top">Beautiful. Looks like a picture that Kiwiness would compose. Very artistic and delicate. Great job.</td>', 'Beautiful. Looks like a picture that Kiwiness would compose. Very artistic and delicate. Great job.', '2008-11-01 12:33:46.000000', NULL, 1),
