INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5049033, 733954, 18655, '<td valign="top">Very sharp and nice effect with the sky. The diagonal lines makes it really stand out.</td>', 'Very sharp and nice effect with the sky. The diagonal lines makes it really stand out.', '2008-11-06 14:49:09.000000', NULL, 1),
